package com.bank.flink.hints;

import java.util.LinkedHashMap;
import java.util.Map;
import java.util.logging.Logger;

// Merges baseline DDL options with a query hint; the hint wins, but the
// shared DDL is never modified (a fresh map is returned).
class OptionResolver {
    private static final Logger log = Logger.getLogger(OptionResolver.class.getName());
    private final boolean hintsEnabled; // table.dynamic-table-options.enabled

    OptionResolver(boolean hintsEnabled) { this.hintsEnabled = hintsEnabled; }

    Map<String, String> resolve(TableOptions ddl, QueryHint hint) {
        Map<String, String> effective = new LinkedHashMap<>(ddl.asMap());
        if (!hintsEnabled) {
            log.warning("dynamic table option hints DISABLED; ignoring OPTIONS");
            return effective;
        }
        hint.asMap().forEach((k, v) -> {
            effective.put(k, v);
            log.info(() -> "hint override " + k + "=" + v);
        });
        return effective;
    }
}
