package com.bank.flink.hints;

import java.util.List;
import java.util.concurrent.CompletableFuture;
import java.util.concurrent.ExecutionException;
import java.util.logging.Logger;

// Runs enrichment lookups either synchronously (blocking, one at a time)
// or asynchronously (many in flight), mirroring the LOOKUP async hint.
class LookupExecutor {
    private static final Logger log = Logger.getLogger(LookupExecutor.class.getName());

    // Simulate a slow dimension lookup (e.g., external DB) ~ 20ms each.
    private int slowLookup(String accountId) {
        try { Thread.sleep(20); } catch (InterruptedException e) { Thread.currentThread().interrupt(); }
        return accountId.hashCode() & 0x3f; // fake risk score 0..63
    }

    long runSync(List<String> accountIds) {
        long start = System.currentTimeMillis();
        for (String id : accountIds) slowLookup(id);
        long elapsed = System.currentTimeMillis() - start;
        log.info(() -> "SYNC lookups took " + elapsed + " ms");
        return elapsed;
    }

    long runAsync(List<String> accountIds) throws ExecutionException, InterruptedException {
        long start = System.currentTimeMillis();
        List<CompletableFuture<Integer>> futures = accountIds.stream()
                .map(id -> CompletableFuture.supplyAsync(() -> slowLookup(id)))
                .toList();
        CompletableFuture.allOf(futures.toArray(new CompletableFuture[0])).get();
        long elapsed = System.currentTimeMillis() - start;
        log.info(() -> "ASYNC lookups took " + elapsed + " ms");
        return elapsed;
    }
}
