package com.bank.flink.hints;

import java.util.List;
import java.util.Map;
import java.util.logging.ConsoleHandler;
import java.util.logging.Formatter;
import java.util.logging.Level;
import java.util.logging.LogRecord;
import java.util.logging.Logger;

public class HintsDemo {
    private static final Logger log = Logger.getLogger(HintsDemo.class.getName());

    static {
        Logger root = Logger.getLogger("");
        for (var h : root.getHandlers()) root.removeHandler(h);
        ConsoleHandler handler = new ConsoleHandler();
        handler.setFormatter(new BankLogFormatter());
        handler.setLevel(Level.ALL);
        root.addHandler(handler);
        root.setLevel(Level.INFO);
    }

    public static void main(String[] args) throws Exception {
        // Baseline shared DDL: read from latest offset.
        TableOptions ddl = new TableOptions()
                .put("connector", "kafka")
                .put("topic", "transactions")
                .put("scan.startup.mode", "latest-offset");

        // Fraud team's per-query OPTIONS hint: replay from earliest.
        QueryHint hint = new QueryHint().override("scan.startup.mode", "earliest-offset");

        OptionResolver resolver = new OptionResolver(true);
        Map<String, String> effective = resolver.resolve(ddl, hint);
        log.info("effective options for this query: " + effective);
        log.info("shared DDL is unchanged: " + ddl.asMap());

        // LOOKUP hint effect: enrich 20 accounts sync vs async.
        List<String> accounts = List.of(
                "SAV2001", "CUR3001", "SAV2002", "CUR3002", "SAV2003",
                "CUR3003", "SAV2004", "CUR3004", "SAV2005", "CUR3005",
                "SAV2006", "CUR3006", "SAV2007", "CUR3007", "SAV2008",
                "CUR3008", "SAV2009", "CUR3009", "SAV2010", "CUR3010");
        LookupExecutor exec = new LookupExecutor();
        long sync = exec.runSync(accounts);
        long async = exec.runAsync(accounts);
        log.info("async speedup roughly " + (sync / Math.max(1, async)) + "x");
    }
}

